Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>

#define dbg(x) cerr << #x << " = " << (x) << endl
#define raya cerr << "-------------------" << endl

using namespace std;

typedef long long ll;

struct step {
	ll val; int cost;
	bool operator<(const step &c) const {
		return c.cost < cost;
	}
};

set<ll> visited;

bool wasVisited(ll c) {
	return visited.find(c) != visited.end();
}

step uupper(ll n){
	ll res = 0;
	int i = 0;
	while(res<n){
		res*=10;
		res++;
		i++;
	}
	return {res, i};
}

step upper(ll n){
	ll res = 0;
	int i = 0;
	while(res*10+1<=n){
		res*=10;
		res++;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res < n){
		res+=resmul;
		i+=imul;
	}
	return {res, i};
}

step lower(ll n){
	ll res = 0;
	int i = 0;
	while(res*10+1<=n){
		res*=10;
		res++;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res+resmul <= n){
		res+=resmul;
		i+=imul;
	}
	return {res, i};
}

int main(int argc, char **argv) {
	ll n;
	cin >> n;

	priority_queue<step> pq;

	pq.push(step{n, 0});

	while(pq.top().val != 0){
		ll val = pq.top().val;
		int cost = pq.top().cost;
		pq.pop();

		if(wasVisited(val))
			continue;
		visited.insert(val);

		for (step next : { lower(val), upper(val), uupper(val) }) {
			next.cost += cost;
			next.val = abs(val - next.val);
			pq.push(next);

		}

	}

	cout << pq.top().cost << endl;
}

</original_code>
